class Solution {
    public int findMinArrowShots(int[][] points) {
        java.util.Arrays.sort(points, (a, b) -> {
            int byStart = Integer.compare(a[0], b[0]);
            return byStart != 0 ? byStart : Integer.compare(a[1], b[1]);
        });
        int arrows = 1;
        int currentEnd = points[0][1];
        for (int i = 1; i < points.length; i++) {
            if (points[i][0] > currentEnd) {
                arrows++;
                currentEnd = points[i][1];
            } else {
                currentEnd = Math.min(currentEnd, points[i][1]);
            }
        }
        return arrows;
    }
}

class Solution {
    public int findMinArrowShots(int[][] points) {
        java.util.Arrays.sort(points, (a, b) -> {
            int byStart = Integer.compare(a[0], b[0]);
            return byStart != 0 ? byStart : Integer.compare(a[1], b[1]);
        });
        java.util.PriorityQueue<Integer> activeEnds = new java.util.PriorityQueue<>();
        int arrows = 0;
        for (int[] point : points) {
            if (!activeEnds.isEmpty() && activeEnds.peek() < point[0]) {
                arrows++;
                activeEnds.clear();
            }
            activeEnds.offer(point[1]);
        }
        return arrows + (activeEnds.isEmpty() ? 0 : 1);
    }
}

import java.util.*;

class Solution {
    public int findMinArrowShots(int[][] points) {
        int[][] events = new int[points.length * 2][3];
        int index = 0;
        for (int i = 0; i < points.length; i++) {
            events[index++] = new int[]{points[i][0], 0, i};
            events[index++] = new int[]{points[i][1], 1, i};
        }
        java.util.Arrays.sort(events, (a, b) -> {
            int byCoordinate = Integer.compare(a[0], b[0]);
            return byCoordinate != 0 ? byCoordinate : Integer.compare(a[1], b[1]);
        });
        Set<Integer> active = new HashSet<>();
        int arrows = 0;
        for (int[] event : events) {
            if (event[1] == 0) {
                active.add(event[2]);
            } else if (active.remove(event[2])) {
                arrows++;
                active.clear();
            }
        }
        return arrows;
    }
}

