class Solution {
    public int findMinArrowShots(int[][] points) {
        java.util.Arrays.sort(points, (a, b) -> Integer.compare(a[1], b[1]));
        TreeSet<Integer> arrows = new TreeSet<>();
        for (int[] point : points) {
            Integer candidate = arrows.ceiling(point[0]);
            if (candidate != null && candidate <= point[1]) {
                continue;
            }
            arrows.add(point[1]);
        }
        return arrows.size();
    }
}
